pgrep -f rc_analytical.py && exit 1; python3 - <<'PY'
import glob,os,time
def s():
    o={}
    for d in glob.glob('/proc/[0-9]*'):
        try:
            c=open(d+'/cmdline','rb').read().replace(b'\0',b' ').decode()
            if c.lower().startswith('oracle') and 'LOCAL=NO' in c:
                f=open(d+'/stat').read().rsplit(')',1)[1].split(); o[d]=(int(f[11])+int(f[12]))/os.sysconf('SC_CLK_TCK')
        except Exception: pass
    return o
quiet=0; t0=time.time()
while time.time()-t0<900:
    a=s(); time.sleep(5); b=s()
    busy={k:round(b[k]-a[k],2) for k in b if k in a and b[k]-a[k]>0.5}
    print(round(time.time()-t0),'busy foregrounds:',busy,flush=True)
    quiet=quiet+1 if not busy else 0
    if quiet>=2: print('oracle idle'); raise SystemExit(0)
raise SystemExit('oracle still busy after 15 min')
